namespace ghidra.app.plugin.core.debug.gui.console;





using docking.widgets.table;
using ghidra.debug.api.progress;
using ghidra.docking.settings;
using ghidra.util.table.column;

public class HtmlOrProgressCellRenderer : GColumnRenderer<object>
{	public static readonly HtmlOrProgressCellRenderer INSTANCE = new();


	static readonly CustomToStringCellRenderer<string> FOR_STRING =
		CustomToStringCellRenderer.HTML;
	static readonly MonitorCellRenderer FOR_MONITOR = MonitorCellRenderer.INSTANCE;

	/* @Override */
	public Component getTableCellRendererComponent(JTable table, object value,
			bool isSelected, bool hasFocus, int row, int column) {
		if (value == null) {
			return FOR_STRING.getTableCellRendererComponent(table, value, isSelected,
				hasFocus, row, column);
		}
		if (value is string message) {
			return FOR_STRING.getTableCellRendererComponent(table, message, isSelected,
				hasFocus, row, column);
		}
		if (value is MonitorReceiver monitor) {
			return FOR_MONITOR.getTableCellRendererComponent(table, monitor, isSelected,
				hasFocus, row, column);
		}
		throw new AssertionError();
	}

	int getRowHeight(int colWidth) {
		return FOR_STRING.getRowHeight(colWidth);
	}

	/* @Override */
	public string getFilterString(object t, Settings settings) {
		if (t == null) {
			return FOR_STRING.getFilterString(null, settings);
		}
		if (t is string message) {
			return FOR_STRING.getFilterString(message, settings);
		}
		if (t is MonitorReceiver monitor) {
			return FOR_MONITOR.getFilterString(monitor, settings);
		}
		throw new AssertionError();
	}
}
